def map_to_3classes(folder_name):
    folder = folder_name.lower()

    if "healthy" in folder:
        return "healthy"

    elif any(k in folder for k in [
        "bacterial", "canker", "anthracnose",
        "die", "mildew", "mould", "spot", "blight"
    ]):
        return "diseased"

    elif any(k in folder for k in [
        "weevil", "mite", "midge"
    ]):
        return "stressed"

    else:
        return "stressed"

