class_labels = [k for k, v in sorted(class_indices.items(), key=lambda x: x[1])]

imgs_collected = {cls: [] for cls in class_labels}
labels_collected = {cls: [] for cls in class_labels}

# ambil data
while any(len(imgs_collected[cls]) < images_per_class for cls in class_labels):
    imgs, labels = next(test_ds)

    for i in range(len(imgs)):
        cls_idx = np.argmax(labels[i])
        cls_name = class_labels[cls_idx]

        if len(imgs_collected[cls_name]) < images_per_class:
            imgs_collected[cls_name].append(imgs[i])
            labels_collected[cls_name].append(labels[i])

# PLOT RAPI PER KELAS
plt.figure(figsize=(10,8))

plot_idx = 1
for cls in class_labels:
    for i in range(images_per_class):
        img = imgs_collected[cls][i]
        true_label = cls

        pred = best_model.predict(np.expand_dims(img, axis=0), verbose=0)
        pred_label = class_labels[np.argmax(pred)]
        confidence = np.max(pred)

        plt.subplot(len(class_labels), images_per_class, plot_idx)
        plt.imshow(img)
        plt.title(f"True: {true_label}\nPred: {pred_label} ({confidence:.2f})")
        plt.axis("off")

        plot_idx += 1

plt.tight_layout()
plt.show()

